const familyOrder=['query','control','goal','aggregate','workflow'];
const subtypeOrder={query:['property.device','property.space','space.person_location','space.occupants','target.quantity','target.enum','target.comparison.top1','target.comparison.topk'],control:['single','multi_property','multi_target','complex'],goal:['single','multi_property','multi_target','complex'],aggregate:['query','control','goal','control_query','control_goal','query_goal','control_query_goal'],workflow:['single','condition_follow','condition_delay','condition_window','synchronize','at','before','environment_deadline','environment_before_process']};
const familyTitle=f=>f[0].toUpperCase()+f.slice(1);
const subtypeCode=(f,s)=>({query:'Q',control:'C',goal:'G',aggregate:'A',workflow:'W'}[f])+(subtypeOrder[f].indexOf(s)+1);
const subtypeLabel=s=>s.replaceAll('_',' ').replaceAll('.',' · ');
const wall=document.getElementById('task-wall'),domainSelect=document.getElementById('wall-domain'),familySelect=document.getElementById('wall-family'),subtypeSelect=document.getElementById('wall-subtype'),pauseButton=document.getElementById('wall-pause');
const motionPreference=matchMedia('(prefers-reduced-motion: reduce)');let wallPaused=motionPreference.matches,wallHover=false,wallFocus=false,wallVisible=false,wallOffset=0,wallRows=[],wallLastTime=0,wallFrame=0;
function updatePause(){pauseButton.textContent=wallPaused?'Resume motion':'Pause motion';pauseButton.setAttribute('aria-pressed',String(wallPaused));}
updatePause();
function options(select,values,allLabel){const previous=select.value;select.replaceChildren(new Option(allLabel,'all'),...values.map(([v,l])=>new Option(l,v)));select.value=values.some(([v])=>v===previous)?previous:'all';}
function syncWallFilters(){const domain=domainSelect.value;const relevant=wallExamples.filter(t=>domain==='all'||t.domain===domain);options(familySelect,familyOrder.filter(f=>relevant.some(t=>t.family===f)).map(f=>[f,familyTitle(f)]),'All families');const f=familySelect.value;const pairs=familyOrder.flatMap(family=>subtypeOrder[family].filter(sub=>relevant.some(t=>t.family===family&&t.subtype===sub)&&(f==='all'||f===family)).map(sub=>[family+'/'+sub,subtypeCode(family,sub)+' · '+subtypeLabel(sub)]));options(subtypeSelect,pairs,'All subtypes');renderWall();}
const dialog=document.getElementById('task-dialog');let lastCard=null;
function openTask(task,button){lastCard=button;document.getElementById('dialog-tags').textContent=task.domain+' / '+familyTitle(task.family)+' / '+subtypeCode(task.family,task.subtype)+' · '+subtypeLabel(task.subtype);document.getElementById('dialog-instruction').textContent=task.instruction;document.getElementById('dialog-source').textContent='Validation · '+task.style+' · '+task.id;dialog.showModal();}
document.getElementById('dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>{if(lastCard?.isConnected)lastCard.focus();});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
function poster(task,index){const button=document.createElement('button');button.type='button';button.className='task-poster domain-'+task.domain.toLowerCase();button.dataset.taskId=task.id;button.setAttribute('aria-label',task.domain+' '+subtypeCode(task.family,task.subtype)+': '+task.instruction);const top=document.createElement('span');top.className='poster-top';const domain=document.createElement('span');domain.textContent=task.domain;const code=document.createElement('span');code.textContent=subtypeCode(task.family,task.subtype);top.append(domain,code);const family=document.createElement('span');family.className='poster-family';family.textContent=familyTitle(task.family);const text=document.createElement('span');text.className='poster-instruction';text.textContent=task.instruction;const bottom=document.createElement('span');bottom.className='poster-bottom';bottom.textContent=subtypeLabel(task.subtype)+' ↗';button.append(top,family,text,bottom);button.addEventListener('click',()=>openTask(task,button));return button;}
function placeRows(){wallRows.forEach(({track,period,stagger})=>{track.style.transform='translateX('+(-((wallOffset+stagger)%period+period)%period)+'px)';});}
function measureWall(){wallRows.forEach(row=>{row.period=row.track.firstElementChild.getBoundingClientRect().width;});placeRows();}
function taskSortKey(t){let h=0;for(const c of t.domain+t.id)h=(Math.imul(h,31)+c.charCodeAt(0))|0;return h>>>0;}
function renderWall(){const filtered=wallExamples.filter(t=>(domainSelect.value==='all'||t.domain===domainSelect.value)&&(familySelect.value==='all'||t.family===familySelect.value)&&(subtypeSelect.value==='all'||t.family+'/'+t.subtype===subtypeSelect.value)).sort((a,b)=>taskSortKey(a)-taskSortKey(b));document.getElementById('wall-count').textContent=filtered.length+' examples · '+new Set(filtered.map(t=>t.family+'/'+t.subtype)).size+' subtypes';wall.replaceChildren();wallRows=[];wallOffset=0;if(!filtered.length){wall.textContent='No examples match this selection.';return;}const rowCount=Math.min(3,filtered.length);for(let row=0;row<rowCount;row++){const items=filtered.filter((_,i)=>i%rowCount===row);const lane=document.createElement('div');lane.className='wall-lane';const track=document.createElement('div');track.className='wall-track';const group=document.createElement('div');group.className='wall-group';items.forEach((task,i)=>group.append(poster(task,i)));track.append(group);lane.append(track);wall.append(lane);const width=group.getBoundingClientRect().width;const copies=Math.max(2,Math.ceil((wall.clientWidth+width)/width));for(let i=1;i<copies;i++){const clone=document.createElement('div');clone.className='wall-group';clone.setAttribute('aria-hidden','true');items.forEach((task,j)=>{const card=poster(task,j);card.tabIndex=-1;clone.append(card);});track.append(clone);}wallRows.push({track,period:width,stagger:row%2?150:0});}placeRows();}
function wallTick(now){const delta=Math.min(now-wallLastTime,60);wallLastTime=now;if(wallVisible&&!wallPaused&&!wallHover&&!wallFocus&&!dialog.open&&!document.hidden){wallOffset+=delta*.022;placeRows();}wallFrame=requestAnimationFrame(wallTick);}
new IntersectionObserver(entries=>{wallVisible=entries[0].isIntersecting;},{rootMargin:'80px'}).observe(wall);
wall.addEventListener('pointerenter',e=>{if(e.pointerType==='mouse')wallHover=true;});wall.addEventListener('pointerleave',()=>wallHover=false);wall.addEventListener('focusin',()=>wallFocus=true);wall.addEventListener('focusout',()=>{wallFocus=wall.contains(document.activeElement);});
pauseButton.addEventListener('click',()=>{wallPaused=!wallPaused;updatePause();});motionPreference.addEventListener('change',e=>{wallPaused=e.matches;updatePause();});
for(const [id,direction] of [['wall-prev',-1],['wall-next',1]])document.getElementById(id).addEventListener('click',()=>{wallPaused=true;updatePause();wallOffset+=direction*340;placeRows();});
let pointerX=null;wall.addEventListener('pointerdown',e=>{if(e.pointerType==='touch')pointerX=e.clientX;});wall.addEventListener('pointerup',e=>{if(pointerX!==null){const distance=pointerX-e.clientX;if(Math.abs(distance)>30){wallPaused=true;updatePause();wallOffset+=distance;placeRows();}pointerX=null;}});
domainSelect.addEventListener('change',syncWallFilters);familySelect.addEventListener('change',syncWallFilters);subtypeSelect.addEventListener('change',renderWall);window.addEventListener('resize',measureWall);syncWallFilters();wallFrame=requestAnimationFrame(wallTick);
